import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Aufnahmebestätigungen aus Schüler Online importieren","description":"","frontmatter":{"title":"Aufnahmebestätigungen aus Schüler Online importieren","source_pageid":1182,"source_revision":5202},"headers":[],"relativePath":"schild3/import-export-statistik/aufnahmebestaetigung-verwaltung-import.md","filePath":"schild3/import-export-statistik/aufnahmebestaetigung-verwaltung-import.md"}'),a={name:"schild3/import-export-statistik/aufnahmebestaetigung-verwaltung-import.md"};function s(u,e,l,o,m,g){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="aufnahmebestatigungen-aus-schuler-online-importieren" tabindex="-1">Aufnahmebestätigungen aus Schüler Online importieren <a class="header-anchor" href="#aufnahmebestatigungen-aus-schuler-online-importieren" aria-label="Permalink to &quot;Aufnahmebestätigungen aus Schüler Online importieren&quot;">​</a></h1><p>Lesen Sie die von Schüler Online bereitgestellte Datei mit Aufnahmebestätigungen in SchILD-NRW ein.</p><p>Über SchülerOnline besteht die Möglichkeit für abgebende Schulen, eine Datei mit Schulwechslern zu exportieren.</p><p>Hierbei wird eine Datei <em>Aufnahmen_SCHULNUMMER_DATUM.txt</em> erzeugt.</p><p>Diese Datei kann in SchILD-NRW über <em>Verwaltung ➜ Import</em> ➜ <strong>Aufnahmebestätigungen</strong> eingelesen werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Aufnahmebest%C3%A4tigung_(Verwaltung_Import)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5202.</p>',7)])])}const c=t(a,[["render",s]]);export{p as __pageData,c as default};
